<?php

declare(strict_types=1);

namespace Padosoft\MobilePush\Core\Apns\Channels;

/** A broadcast channel as APNs reports it. The id is opaque: Apple says "don't make assumptions on the channel ID size". */
final readonly class Channel
{
    public const PUSH_TYPE_LIVE_ACTIVITY = 'LiveActivity';

    public function __construct(
        /** Base64 string generated by APNs. */
        public string $id,
        public StoragePolicy $storagePolicy,
        public string $pushType = self::PUSH_TYPE_LIVE_ACTIVITY,
    ) {}
}
